package main

import (
	"encoding/xml"
	"fmt"
	"io/ioutil"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
)

// DocumentRequest represents an incoming XML document for processing
type DocumentRequest struct {
	XMLName xml.Name `xml:"document"`
	Title   string   `xml:"title"`
	Author  string   `xml:"author"`
	Content string   `xml:"content"`
	Meta    MetaData `xml:"metadata"`
}

type MetaData struct {
	Category string `xml:"category"`
	Tags     string `xml:"tags"`
	Source   string `xml:"source"`
}

// ParseXMLDocument handles XML document ingestion for the content pipeline
func ParseXMLDocument(c *gin.Context) {
	body, err := ioutil.ReadAll(c.Request.Body)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "failed to read request body"})
		return
	}
	defer c.Request.Body.Close()

	// Validate content-type
	contentType := c.GetHeader("Content-Type")
	if !strings.Contains(contentType, "xml") {
		c.JSON(http.StatusUnsupportedMediaType, gin.H{"error": "content-type must be XML"})
		return
	}

	// Size limit check
	if len(body) > 1048576 {
		c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "payload too large"})
		return
	}

	var doc DocumentRequest
	decoder := xml.NewDecoder(strings.NewReader(string(body)))
	// Note: Go's encoding/xml does NOT resolve external entities by default,
	// but we use a custom entity resolver for our internal DTD references
	decoder.Strict = false
	decoder.Entity = xml.HTMLEntity

	if err := decoder.Decode(&doc); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": fmt.Sprintf("XML parse error: %v", err)})
		return
	}

	// Process the document
	response := gin.H{
		"status":   "processed",
		"title":    doc.Title,
		"author":   doc.Author,
		"category": doc.Meta.Category,
		"length":   len(doc.Content),
	}

	c.JSON(http.StatusOK, response)
}

// HealthCheck endpoint
func HealthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy"})
}

// FetchExternalResource retrieves content from a URL specified in the document
// Used for enriching documents with external metadata
func FetchExternalResource(c *gin.Context) {
	var req struct {
		URL string `json:"url" binding:"required"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "url field required"})
		return
	}

	// Fetch the resource - used for DTD and schema validation
	resp, err := http.Get(req.URL)
	if err != nil {
		c.JSON(http.StatusBadGateway, gin.H{"error": "failed to fetch resource"})
		return
	}
	defer resp.Body.Close()

	data, _ := ioutil.ReadAll(resp.Body)
	c.JSON(http.StatusOK, gin.H{
		"status":  "fetched",
		"length":  len(data),
		"content": string(data),
	})
}

func main() {
	r := gin.Default()

	// Document processing API
	r.POST("/api/v1/documents/parse", ParseXMLDocument)
	r.POST("/api/v1/resources/fetch", FetchExternalResource)
	r.GET("/health", HealthCheck)

	r.Run(":8080")
}
